/** @jsxImportSource ../ */
import { Suspense, renderToReadableStream } from '../streaming'
import { createContext, useContext } from '../context'
import { jsx } from '../base'
import { Hono } from '../../hono'
import { jsxRenderer } from '../../middleware/jsx-renderer'

const read = async (s: ReadableStream) => { const r = s.getReader(); let o=''; const d=new TextDecoder(); for(;;){const {done,value}=await r.read(); if(done)break; o+=d.decode(value)} return o }
describe('arr', () => {
  it('sync', async () => {
    const Items = () => [<li>a</li>, <li>&amp;{'<b>'}</li>, [<i>n</i>]]
    expect((<ul><Items/></ul>).toString()).toBe('<ul><li>a</li><li>&amp;&lt;b&gt;</li><i>n</i></ul>')
  })
  it('async title', async () => {
    const A = async () => [<title>T</title>, <p>x</p>]
    const s = await (<html><head></head><body><A/></body></html>).toString()
    console.log(s)
    const st = await read(renderToReadableStream(<html><head></head><body><Suspense fallback="f"><A/></Suspense></body></html>))
    console.log(st)
  })
  it('ctx', async () => {
    const C = createContext('d')
    const p = Promise.resolve(<div/>)
    const In = async () => { const v = useContext(C); return [<b>{v}</b>] }
    const el = <><C.Provider value="1"><In/></C.Provider><C.Provider value="2"><In/></C.Provider></>
    console.log(await el.toString())
  })
  it('renderer', async () => {
    const app = new Hono()
    app.use(jsxRenderer(({children}) => <html><body>{children}</body></html>))
    const A = async () => [<title>T</title>, <p>x</p>]
    app.get('/', (c) => c.render(<A/>))
    console.log(await (await app.request('/')).text())
  })
})
EOF
